import math

def pick(choice_logprobs, choice_lens, normalize=False):
    scores = {}
    for k, lp in choice_logprobs.items():
        scores[k] = lp / choice_lens[k] if normalize else lp
    return max(scores, key=scores.get)

lp   = {"A": -12.0, "B": -9.0, "C": -15.0, "D": -11.0}   # 보기 문장 로그확률 합
lens = {"A": 4, "B": 3, "C": 5, "D": 6}                 # 보기 토큰 수
print(pick(lp, lens))                  # B  (합 기준)
print(pick(lp, lens, normalize=True))  # D  (토큰당 평균 기준)

# (나) 방식: 다음 토큰을 A~D 로 제한
next_tok = {"A": 0.30, "B": 0.25, "C": 0.05, "D": 0.40}
print(max(next_tok, key=next_tok.get))  # D

# 오염 검사 아이디어(의사코드): 원래 순서 vs 섞은 순서의 로그우도 차이
def contamination_gap(logp_fn, examples, shuffles):
    base = logp_fn("\n".join(examples))
    others = [logp_fn("\n".join(s)) for s in shuffles]
    return base - sum(others) / len(others)   # 크게 양수면 의심
